"""Admin panel translations — 8 languages (en, uk, ru, de, tr, es, it, fr).

The panel's templates (node/admin.py) and its server messages (diagnostics.py, AIBotError
texts, admin.py error replies) keep their Russian source text; localize() swaps every known
phrase for the chosen language when a page or a message is served. One left-to-right pass,
longest phrase first, so a translation is never translated again (Ukrainian shares letters
with Russian) and a short phrase never bites into a longer one.

Each entry: source phrase -> (en, uk, ru, de, tr, es, it, fr); None = same as the source.
A phrase is a run of text between markup/quotes — see SEGMENT, the test extracts them the
same way and fails on any phrase without a full row. Translations go into HTML and into JS
string literals as-is, so they must not contain ' " ` < > & or a backslash unless the source
phrase does (use ’ for apostrophes).
"""
import re

LANGS = ("en", "uk", "ru", "de", "tr", "es", "it", "fr")
DEFAULT_LANG = "en"
LANG_NAMES = {"en": "English", "uk": "Українська", "ru": "Русский", "de": "Deutsch",
              "tr": "Türkçe", "es": "Español", "it": "Italiano", "fr": "Français"}
COOKIE = "nevod_admin_lang"

# How a phrase is cut out of a template: Cyrillic plus whatever surrounds it up to markup,
# quotes, newlines, backslashes or ${...} — a JS "\n" escape stays inside the phrase.
# Shared with tests/test_admin_i18n.py.
_CHAR = r"(?:[^<>'\"`\n\\{}]|\\n)"
SEGMENT = re.compile(_CHAR + r"*[А-Яа-яЁёІіЇїЄєҐґ]" + _CHAR + "*")

