_IDX = {lang: i for i, lang in enumerate(LANGS)}
_PATTERN = re.compile("|".join(re.escape(k) for k in sorted(CATALOG, key=len, reverse=True)))


def translate(phrase: str, lang: str) -> str:
    row = CATALOG.get(phrase)
    if row is None:
        return phrase
    text = row[_IDX[lang]]
    return phrase if text is None else text


def localize(text: str, lang: str) -> str:
    """Every catalog phrase in `text` in `lang` — one pass, so nothing is translated twice."""
    if lang not in _IDX:
        lang = DEFAULT_LANG
    return _PATTERN.sub(lambda m: translate(m.group(), lang), text)


def pick_lang(cookie: str | None, accept_language: str | None) -> str:
    """The admin's choice (cookie), else the browser's first supported language, else English."""
    if cookie in _IDX:
        return cookie
    for part in (accept_language or "").split(","):
        code = part.split(";")[0].strip().lower()[:2]
        if code in _IDX:
            return code
    return DEFAULT_LANG
